// tools/check-client-safe-enum-scope.mjs
//
// lib/prismaEnums.ts is a COPY. It may only be imported by code that actually
// reaches the browser.
//
// The copy exists for one reason: a value import of '@prisma/client' cannot be
// erased, so it drags that package's browser build into the client bundle. That
// argument applies to client-reachable code and nowhere else. A server module
// importing the copy pays nothing for it and gives up something real — the
// generated client, which is the schema, in favour of a file regenerated by a
// script.
//
// Both definitions are held equal by check:client-safe-enums, so a mixed code
// path is not a correctness bug today: the members are the same strings, and
// every comparison in this repo is by value. The reason to hold the line anyway
// is that "equal" is a property maintained by a guard, and the set of code
// depending on that guard should be the smallest set that needs to. Server code
// has the real enum available for free; let it use the real enum.
//
// Reachability is computed the same way check-no-client-prisma-import.mjs
// computes it — BFS over VALUE imports from every 'use client' module, stopping
// at a 'use server' boundary — so the two guards agree on what "reaches the
// browser" means. A module reachable from a client component is allowed even if
// the server also calls it: shared presentation helpers like
// lib/booking/statusLabel.ts are exactly the case this file is for.
//
// Test files are exempt. A test that imports both definitions in order to assert
// they agree is the opposite of the problem, and nothing under test ships.
//
// Usage:
//   node tools/check-client-safe-enum-scope.mjs

import fs from 'node:fs'
import path from 'node:path'

const ROOT = process.cwd()
const COPY = 'lib/prismaEnums.ts'
const COPY_ABS = path.join(ROOT, COPY)
const COPY_SPECIFIERS = new Set(['@/lib/prismaEnums'])

const SCAN_DIRS = ['app', 'lib', 'components', 'hooks', 'contexts', 'providers']
const EXTENSIONS = ['.ts', '.tsx', '.js', '.jsx', '.mts', '.mjs']
const IGNORE_DIRS = new Set([
  'node_modules',
  '.next',
  'dist',
  'build',
  'coverage',
  '.claude',
])

// Enough of the file to be sure a leading directive is in it. 500 was not:
// app/client/(gated)/settings/ClientChartSharingSettings.tsx carries an
// explanatory header and its 'use client' lands at byte 491. This guard and
// check-no-client-prisma-import must agree on what reaches the browser, so they
// read the same window and use the same matcher.
const HEAD_BYTES = 8000

const FROM_RE =
  /(?:^|\n)[ \t]*(?:import|export)[ \t]+([\s\S]*?)[ \t]*from[ \t]*['"]([^'"]+)['"]/g
const SIDE_EFFECT_RE = /(?:^|\n)[ \t]*import[ \t]*['"]([^'"]+)['"]/g
const DYNAMIC_RE = /\bimport[ \t]*\([ \t]*['"]([^'"]+)['"][ \t]*\)/g

// A leading directive, after any run of header comments.
//
// WARNING: the `\\s*` after the line-comment arm is load-bearing. Without it the
// matcher accepted `// header` + newline + `'use client'` but NOT the far
// commoner form with a BLANK LINE between them — one blank line, and a client
// component read as a server module. That silently hid 23 of this repo's 342
// client components from both this guard and check-client-safe-enum-scope,
// including the two that kept the @prisma/client browser chunk on three routes
// after the money.ts split had removed every other cause. A guard that
// under-reports its own input set passes for the wrong reason, which is worse
// than failing.
const DIRECTIVE_RE = (name) =>
  new RegExp(
    `^\\s*(?:\\/\\/[^\\n]*\\n\\s*|\\/\\*[\\s\\S]*?\\*\\/\\s*)*['"]use ${name}['"]`,
  )
const USE_CLIENT_RE = DIRECTIVE_RE('client')
const USE_SERVER_RE = DIRECTIVE_RE('server')

function listFiles(dir, out = []) {
  let entries
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true })
  } catch {
    return out
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.') || IGNORE_DIRS.has(entry.name)) continue
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) listFiles(full, out)
    else if (EXTENSIONS.includes(path.extname(entry.name))) out.push(full)
  }
  return out
}

function resolveSpecifier(spec, fromFile) {
  let base
  if (spec.startsWith('@/')) base = path.join(ROOT, spec.slice(2))
  else if (spec.startsWith('.')) base = path.resolve(path.dirname(fromFile), spec)
  else return null

  for (const ext of ['', ...EXTENSIONS]) {
    const candidate = base + ext
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate
  }
  for (const ext of EXTENSIONS) {
    const candidate = path.join(base, `index${ext}`)
    if (fs.existsSync(candidate)) return candidate
  }
  return null
}

/** True when the import clause is erased by TypeScript and reaches no bundler. */
function isTypeOnlyClause(clause) {
  if (/^type\b/.test(clause)) return true
  const braced = clause.match(/\{([\s\S]*)\}/)
  if (!braced) return false
  if (clause.slice(0, clause.indexOf('{')).trim().replace(/,$/, '').length > 0) {
    return false
  }
  const names = braced[1]
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
  return names.length > 0 && names.every((n) => /^type\s/.test(n))
}

const sourceCache = new Map()
function read(file) {
  if (!sourceCache.has(file)) {
    try {
      sourceCache.set(file, fs.readFileSync(file, 'utf8'))
    } catch {
      sourceCache.set(file, '')
    }
  }
  return sourceCache.get(file)
}

function valueDeps(file) {
  const src = read(file)
  const out = []
  for (const m of src.matchAll(FROM_RE)) {
    if (isTypeOnlyClause(m[1])) continue
    const r = resolveSpecifier(m[2], file)
    if (r) out.push(r)
  }
  for (const m of src.matchAll(SIDE_EFFECT_RE)) {
    const r = resolveSpecifier(m[1], file)
    if (r) out.push(r)
  }
  for (const m of src.matchAll(DYNAMIC_RE)) {
    const r = resolveSpecifier(m[1], file)
    if (r) out.push(r)
  }
  return out
}

/** Every import of the copy, type-only ones included. */
function importsCopy(file) {
  const src = read(file)
  for (const m of src.matchAll(FROM_RE)) {
    if (COPY_SPECIFIERS.has(m[2])) return true
    const resolved = resolveSpecifier(m[2], file)
    if (resolved === COPY_ABS) return true
  }
  for (const m of src.matchAll(DYNAMIC_RE)) {
    if (COPY_SPECIFIERS.has(m[1])) return true
    const resolved = resolveSpecifier(m[1], file)
    if (resolved === COPY_ABS) return true
  }
  return false
}

const isTestFile = (rel) =>
  rel.includes('.test.') || rel.includes('.spec.') || rel.includes('/__tests__/')

/**
 * A guard whose matchers quietly stop matching is worse than no guard. Prove the
 * two behaviours this one rests on before trusting its verdict.
 */
function assertMatchersWork() {
  if (!fs.existsSync(COPY_ABS)) {
    throw new Error(
      `${COPY} does not exist. It is generated — run ` +
        '`node tools/generate-client-safe-enums.mjs --write` — or, if it was ' +
        'deliberately removed, delete this guard with it.',
    )
  }

  const probe = path.join(ROOT, '__scope_probe__.ts')
  const cases = [
    [`import { BookingStatus } from '@/lib/prismaEnums'`, true, 'value import'],
    [`import type { BookingStatus } from '@/lib/prismaEnums'`, true, 'type import'],
    [`import { BookingStatus } from '@prisma/client'`, false, 'prisma import'],
    [`import { x } from '@/lib/prismaEnumsOther'`, false, 'prefix near-miss'],
  ]
  for (const [line, expected, label] of cases) {
    sourceCache.set(probe, line)
    const got = importsCopy(probe)
    sourceCache.delete(probe)
    if (got !== expected) {
      throw new Error(
        `self-test failed: ${label}\n  ${line}\n  expected ${expected}, got ${got}`,
      )
    }
  }

  if (!USE_CLIENT_RE.test("'use client'\nimport x from 'y'")) {
    throw new Error("self-test: 'use client' not detected")
  }
  if (USE_CLIENT_RE.test("import x from 'y'\n'use client'")) {
    throw new Error('self-test: directive must lead the file')
  }
}

function main() {
  try {
    assertMatchersWork()
  } catch (error) {
    console.error(`\ncheck-client-safe-enum-scope: ${error.message}\n`)
    process.exit(1)
  }

  const files = SCAN_DIRS.flatMap((dir) => listFiles(path.join(ROOT, dir)))
  const clientEntries = files.filter((f) => USE_CLIENT_RE.test(read(f).slice(0, HEAD_BYTES)))

  // Everything a client bundle can pull in, by the same rules as
  // check-no-client-prisma-import.
  const reachable = new Set(clientEntries)
  const queue = [...clientEntries]
  while (queue.length > 0) {
    const current = queue.shift()
    for (const dep of valueDeps(current)) {
      if (reachable.has(dep)) continue
      if (USE_SERVER_RE.test(read(dep).slice(0, HEAD_BYTES))) continue
      reachable.add(dep)
      queue.push(dep)
    }
  }

  const violations = []
  for (const file of files) {
    if (file === COPY_ABS) continue
    const rel = path.relative(ROOT, file).split(path.sep).join('/')
    if (isTestFile(rel)) continue
    if (!importsCopy(file)) continue
    if (reachable.has(file)) continue
    violations.push(rel)
  }

  if (violations.length > 0) {
    console.error('\ncheck-client-safe-enum-scope: failed\n')
    console.error(
      `${COPY} is a generated COPY of the schema's enums, kept for code that\n` +
        'reaches the browser. These modules are not reachable from any client\n' +
        'component, so they pay the copy\'s maintenance cost and get nothing for\n' +
        'it — import the real enum instead:\n\n' +
        "  import { BookingStatus } from '@prisma/client'\n\n" +
        'If a module IS meant to be client-reachable and this guard disagrees, the\n' +
        'import chain is the thing to fix, not this list — the same traversal\n' +
        'decides what check-no-client-prisma-import protects.\n',
    )
    for (const v of violations) console.error(`  ${v}`)
    console.error(`\nFound ${violations.length} server-only importer(s) of ${COPY}.`)
    process.exit(1)
  }

  const importers = files.filter(
    (f) => f !== COPY_ABS && importsCopy(f) && reachable.has(f),
  ).length

  console.log(
    `check-client-safe-enum-scope: passed ` +
      `(${importers} client-reachable importers of ${COPY}, no server-only ones)`,
  )
}

main()
